supplementarySelectionPatch:
--- excel_vbe_oracle_worker.ps1
+++ selection-worker.ps1
@@ -1045,6 +1045,27 @@
     }
     finally {
         try { [XlideVbeDialogWatcher]::Stop() } catch { }
+        # Supplementary evidence only: read the selection after a compile dialog.
+        if ($result.stage -eq "compile_dialog" -and $null -ne $excel) {
+            try {
+                $pane = $excel.VBE.ActiveCodePane
+                [int]$startLine = 0; [int]$startColumn = 0; [int]$endLine = 0; [int]$endColumn = 0
+                $pane.GetSelection([ref]$startLine, [ref]$startColumn, [ref]$endLine, [ref]$endColumn)
+                $selectedModule = $pane.CodeModule
+                $lineText = [string]$selectedModule.Lines($startLine, 1)
+                $selectedText = $null
+                if ($startLine -eq $endLine -and $startColumn -ge 1 -and $endColumn -ge $startColumn -and $endColumn -le $lineText.Length + 1) {
+                    $selectedText = $lineText.Substring($startColumn - 1, $endColumn - $startColumn)
+                }
+                $result.selection = [ordered]@{
+                    moduleName = [string]$selectedModule.Parent.Name
+                    startLine = $startLine; startColumn = $startColumn
+                    endLine = $endLine; endColumn = $endColumn
+                    lineText = $lineText; selectedText = $selectedText
+                    storedSource = [string]$selectedModule.Lines(1, $selectedModule.CountOfLines)
+                }
+            } catch { $result.selectionError = $_.Exception.Message }
+        }
         $closed = $true
         if ($null -ne $workbook) {
             try { $workbook.Close($false) } catch { $closed = $false }
